		c := strings.TrimSpace(code)
		if c == "" {
			return false
		}
		if reqQual != "" && strings.EqualFold(c, reqQual) {
			return true
		}
		if stName != "" && strings.EqualFold(c, stName) {
			return true
		}
		return false
	}

