	for _, q := range u.Qualifications {
		if matchesCode(q) {
			hasQual = true
			break
		}
	}

	hasMatchingCert := false
	certActive := false
	for _, cert := range u.Certifications {
		if matchesCode(cert.Code) {
			hasMatchingCert = true
			if cert.Active {
				expired := false
