						}
					}
				}
				if !expired {
					certActive = true
					break
				}
			}
		}
	}

	if hasMatchingCert {
		return true, certActive
	}
	if hasQual {
		// If user has certifications list with all inactive entries, check if any is inactive
		if len(u.Certifications) > 0 {
			anyActive := false
			for _, cert := range u.Certifications {
				if cert.Active {
					if cert.ExpiresAt != "" {
						if exp, err := parseTime(cert.ExpiresAt); err == nil && refTime.After(exp) {
							continue
						}
					}
					anyActive = true
				}
			}
			if !anyActive {
