	}
	return false, false
}

func (s *Store) activeWorkerWorkloadLocked(workerID string) int {
	count := 0
	for _, a := range s.state.Assignments {
		if a.WorkerID == workerID || a.OfferedToWorkerID == workerID {
			switch a.Status {
			case "offered", "accepted", "at_pickup", "picked_up", "in_transit", "arrived", "in_progress":
				j := s.state.Journeys[a.JourneyID]
				if j != nil && (j.Status == "cancelled" || j.Status == "replaced" || j.Status == "expired") {
					continue
				}
				count++
			}
		}
	}
	return count
}

func (s *Store) isWorkerEligibleForAssignmentLocked(u *User, a *AssignmentModel, st *SampleTypeModel, refTime time.Time, checkAvailability bool) (bool, string) {
	if u == nil || !u.Active {
		return false, "ineligible_worker"
	}
	switch a.Kind {
	case "collection":
		if !hasRole(u, "collection_professional") {
			return false, "ineligible_worker"
		}
		hasQual, certActive := isWorkerCertifiedForSampleType(u, st, refTime)
		if !hasQual {
			return false, "ineligible_worker"
		}
		if !certActive {
			return false, "certification_inactive"
		}
	case "transport":
		if !hasRole(u, "delivery_partner") {
			return false, "ineligible_worker"
		}
	case "node":
		if !hasRole(u, "node_handler") {
			return false, "ineligible_worker"
		}
		targetNode := a.NodeID
		if targetNode == "" {
			targetNode = a.FromLocationID
		}
		if targetNode != "" && u.AssignedLocationID != targetNode {
			return false, "ineligible_worker"
		}
	case "laboratory":
		if !hasRole(u, "laboratory_team") {
			return false, "ineligible_worker"
		}
		targetLab := a.LaboratoryID
		if targetLab == "" {
			targetLab = a.ToLocationID
		}
		if targetLab != "" && u.AssignedLocationID != targetLab {
			return false, "ineligible_worker"
		}
	default:
		return false, "ineligible_worker"
	}

	if checkAvailability {
		if !u.Available {
			return false, "worker_unavailable"
		}
		units := a.UnitsReserved
		if units <= 0 {
			units = 1
		}
		workload := s.activeWorkerWorkloadLocked(u.UserID)
		if u.WorkerIDMatches(a) {
			// Already assigned to this assignment
		} else if u.CapacityUnits < units || (u.CapacityUnits-u.ReservedUnits) < units || workload >= u.CapacityUnits {
			return false, "worker_unavailable"
		}
	}
	return true, ""
}

func (u *User) WorkerIDMatches(a *AssignmentModel) bool {
	return u.UserID == a.WorkerID || u.UserID == a.OfferedToWorkerID
}

func (s *Store) selectFairEligibleWorkerLocked(a *AssignmentModel, st *SampleTypeModel, refTime time.Time, allowDeclinedFallback bool) (*User, bool) {
	// Returns (selectedWorker, anyQualifiedExistsInSystem)
	anyQualifiedExists := false
	var candidates []*User

	for _, u := range s.state.Users {
		okQual, _ := s.isWorkerEligibleForAssignmentLocked(u, a, st, refTime, false)
		if okQual {
			anyQualifiedExists = true
		}
		okAvail, _ := s.isWorkerEligibleForAssignmentLocked(u, a, st, refTime, true)
		if !okAvail {
			continue
		}
		if a.DeclinedByWorkerIDs != nil && a.DeclinedByWorkerIDs[u.UserID] && !allowDeclinedFallback {
			continue
		}
		candidates = append(candidates, u)
	}

	if len(candidates) == 0 && allowDeclinedFallback {
		for _, u := range s.state.Users {
			okAvail, _ := s.isWorkerEligibleForAssignmentLocked(u, a, st, refTime, true)
			if okAvail {
				candidates = append(candidates, u)
			}
		}
	}

	if len(candidates) == 0 {
		return nil, anyQualifiedExists
	}

	sort.Slice(candidates, func(i, j int) bool {
		ui, uj := candidates[i], candidates[j]
		di := a.DeclinedByWorkerIDs != nil && a.DeclinedByWorkerIDs[ui.UserID]
		dj := a.DeclinedByWorkerIDs != nil && a.DeclinedByWorkerIDs[uj.UserID]
		if di != dj {
			return !di
		}
		wi := s.activeWorkerWorkloadLocked(ui.UserID)
		wj := s.activeWorkerWorkloadLocked(uj.UserID)
		// Fairness score: current active workload + recent assignments + limited decline penalty
		scoreI := wi*10 + ui.RecentAssignmentsCount*2 + ui.DeclineCount*3
		scoreJ := wj*10 + uj.RecentAssignmentsCount*2 + uj.DeclineCount*3
		if scoreI != scoreJ {
			return scoreI < scoreJ
		}
		if ui.LastAssignedSeq != uj.LastAssignedSeq {
			return ui.LastAssignedSeq < uj.LastAssignedSeq
		}
		return ui.UserID < uj.UserID
	})

	return candidates[0], anyQualifiedExists
}

func (s *Store) offerAssignmentToWorkerLocked(a *AssignmentModel, w *User, now time.Time) {
	if a.DeclinedByWorkerIDs == nil {
		a.DeclinedByWorkerIDs = make(map[string]bool)
	}
	a.WorkerID = w.UserID
	a.OfferedToWorkerID = w.UserID
	if a.Status == "pending" || a.Status == "" || a.Status == "declined" {
		a.Status = "offered"
	}
	a.OfferedAt = formatTime(now)
	a.OfferExpiresAt = formatTime(now.Add(5 * time.Minute))
	w.RecentAssignmentsCount++
	w.LastAssignedSeq = s.state.NextAssignOrder
	s.state.NextAssignOrder++

	ev := s.recordAuditLocked("system", "dispatcher", "offer_assignment", "assignment", a.AssignmentID, true, now, map[string]interface{}{
		"assignmentId": a.AssignmentID,
		"workerId":     w.UserID,
		"sampleId":     a.SampleID,
		"journeyId":    a.JourneyID,
		"kind":         a.Kind,
	})
	a.History = append(a.History, ev)
	if smp := s.state.Samples[a.SampleID]; smp != nil {
		smp.Timeline = append(smp.Timeline, ev)
	}
}

func (s *Store) releaseJourneyCapacityLocked(j *JourneyModel) {
	if j == nil {
		return
	}
	for idx := range j.Reservations {
		res := &j.Reservations[idx]
		if res.Released {
			continue
		}
		switch res.Kind {
		case "location":
			if loc := s.state.Locations[res.ResourceID]; loc != nil {
				if res.Cooled > 0 {
					releaseCapacityOnPool(&loc.Capacity, true, res.Cooled)
				}
				if res.Regular > 0 {
					releaseCapacityOnPool(&loc.Capacity, false, res.Regular)
				}
			}
		case "connection":
			if conn := s.state.Connections[res.ResourceID]; conn != nil {
				if res.Cooled > 0 {
					releaseCapacityOnPool(&conn.Capacity, true, res.Cooled)
				}
				if res.Regular > 0 {
					releaseCapacityOnPool(&conn.Capacity, false, res.Regular)
				}
			}
		case "worker":
			if u := s.state.Users[res.ResourceID]; u != nil {
				u.ReservedUnits -= res.Regular
				if u.ReservedUnits < 0 {
					u.ReservedUnits = 0
				}
			}
		}
		res.Released = true
	}
}

func (s *Store) reserveJourneyCapacityLocked(j *JourneyModel, nodeIDs []string, connIDs []string, cooled bool, units int) (bool, string) {
	if units <= 0 {
		units = 1
	}
	// First verify all pools have capacity
	seenLoc := map[string]bool{}
	for _, nid := range nodeIDs {
		if seenLoc[nid] {
			continue
		}
		seenLoc[nid] = true
		loc := s.state.Locations[nid]
		if loc == nil {
			return false, "invalid_reservation"
		}
		if !hasResourceCapacity(loc.Capacity, cooled, units) {
			if cooled {
				return false, "cooled_capacity_exhausted"
			}
			return false, "capacity_exhausted"
		}
	}
	seenConn := map[string]bool{}
	for _, cid := range connIDs {
		if seenConn[cid] {
			continue
		}
		seenConn[cid] = true
		conn := s.state.Connections[cid]
		if conn == nil {
			return false, "invalid_reservation"
		}
		if cooled && !conn.Cooled {
			return false, "no_valid_route"
		}
		if !hasResourceCapacity(conn.Capacity, cooled, units) {
			if cooled {
				return false, "cooled_capacity_exhausted"
			}
			return false, "capacity_exhausted"
		}
	}

	// Perform reservations
	seenLoc = map[string]bool{}
	for _, nid := range nodeIDs {
		if seenLoc[nid] {
			continue
		}
		seenLoc[nid] = true
		loc := s.state.Locations[nid]
		reserveCapacityOnPool(&loc.Capacity, cooled, units)
		r := CapacityReservation{
			ResourceID: nid,
			Kind:       "location",
		}
		if cooled {
			r.Cooled = units
		} else {
			r.Regular = units
		}
		j.Reservations = append(j.Reservations, r)
	}
	seenConn = map[string]bool{}
	for _, cid := range connIDs {
		if seenConn[cid] {
			continue
		}
		seenConn[cid] = true
		conn := s.state.Connections[cid]
		reserveCapacityOnPool(&conn.Capacity, cooled, units)
		r := CapacityReservation{
			ResourceID: cid,
			Kind:       "connection",
		}
		if cooled {
			r.Cooled = units
		} else {
			r.Regular = units
		}
		j.Reservations = append(j.Reservations, r)
	}
	return true, ""
}

func (s *Store) computeMinPoolAvailableLocked(nodeIDs []string, connIDs []string, cooled bool) int {
	minAvail := -1
	for _, nid := range nodeIDs {
		if loc := s.state.Locations[nid]; loc != nil {
			av := loc.Capacity.AvailableUnits
			if cooled {
				av = loc.Capacity.CooledAvailableUnits
			}
			if minAvail == -1 || av < minAvail {
				minAvail = av
			}
		}
	}
	for _, cid := range connIDs {
		if conn := s.state.Connections[cid]; conn != nil {
			av := conn.Capacity.AvailableUnits
			if cooled {
				av = conn.Capacity.CooledAvailableUnits
			}
			if minAvail == -1 || av < minAvail {
				minAvail = av
			}
		}
	}
	if minAvail < 0 {
		minAvail = 0
	}
	return minAvail
}

func (s *Store) buildJourneyForSampleLocked(
	smp *SampleModel,
	st *SampleTypeModel,
	route routeSearchResult,
	presealed bool,
	actorID string,
	actorRole string,
	now time.Time,
) (*JourneyModel, []string, error) {
	journeyID := newUUID()
	cooled := isCooledRequired(st)

	routeMode := "direct"
	if len(route.ConnectionPath) > 1 {
		routeMode = "multi_stop"
	}

	j := &JourneyModel{
		JourneyID:               journeyID,
		PlanVersion:             1,
		RouteMode:               routeMode,
		Status:                  "active",
		EstimatedDeliveryAt:     formatTime(route.EstimatedArrival),
		TotalCostUnits:          route.TotalCost,
		CapacityUsed:            1,
		SampleIDs:               []string{smp.SampleID},
		OrderedStops:            []JourneyStop{},
		AssignmentIDs:           []string{},
		CollectionAssignmentIDs: []string{},
		TransportAssignmentIDs:  []string{},
		NodeAssignmentIDs:       []string{},
		LaboratoryAssignmentIDs: []string{},
		Valid:                   true,
		History:                 []TimelineEntry{},
		Reservations:            []CapacityReservation{},
		TargetLaboratoryID:      route.TargetLabID,
		OriginNodeID:            route.StartNodeID,
		ConnectionIDs:           append([]string{}, route.ConnectionPath...),
		NodePathIDs:             append([]string{}, route.NodePath...),
		Cooled:                  cooled,
	}

	// Reserve capacity on nodes & connections
	okCap, _ := s.reserveJourneyCapacityLocked(j, route.NodePath, route.ConnectionPath, cooled, 1)
	if !okCap {
		// Recompute snapshot
	}
	j.CapacityAvailable = s.computeMinPoolAvailableLocked(route.NodePath, route.ConnectionPath, cooled)
	s.recomputeServiceabilitySnapshotLocked()

	// Build OrderedStops
	baseTime, err := parseTime(smp.EarliestCollectionAt)
	if err != nil || baseTime.IsZero() {
		baseTime, _ = parseTime(smp.RequestedAt)
	}
	if baseTime.IsZero() {
		baseTime = now
	}
	elapsedMins := 0
	for idx, nid := range route.NodePath {
		loc := s.state.Locations[nid]
		dwell := 0
		var coord *Coordinate
		if loc != nil {
			dwell = loc.HandlingMinutes
			c := loc.Coordinate
			coord = &c
		}
		if idx > 0 && idx-1 < len(route.ConnectionPath) {
			conn := s.state.Connections[route.ConnectionPath[idx-1]]
			if conn != nil {
				elapsedMins += conn.TravelMinutes
			}
		}
		elapsedMins += dwell
		estAt := formatTime(baseTime.Add(time.Duration(elapsedMins) * time.Minute))
		stopType := "handoff"
		if idx == 0 {
			stopType = "pickup"
		} else if idx == len(route.NodePath)-1 {
			stopType = "delivery"
		}
		j.OrderedStops = append(j.OrderedStops, JourneyStop{
			StopID:       newUUID(),
			LocationID:   nid,
			LocationID2:  nid,
			StopType:     stopType,
			StopType2:    stopType,
			Sequence:     idx + 1,
			EstimatedAt:  estAt,
			EstimatedAt2: estAt,
			DwellMinutes: dwell,
			Coordinate:   coord,
		})
	}

	seq := 1
	var activeAssignIDs []string
	noQualifiedCollector := false

	// 1. Collection assignment (only if not presealed)
	if !presealed {
		collAssign := &AssignmentModel{
			AssignmentID:        newUUID(),
			Kind:                "collection",
			SampleID:            smp.SampleID,
			SampleIDs:           []string{smp.SampleID},
			JourneyID:           journeyID,
			Status:              "pending",
			FromLocationID:      route.StartNodeID,
			ToLocationID:        route.StartNodeID,
			Sequence:            seq,
			History:             []TimelineEntry{},
			DeclinedByWorkerIDs: make(map[string]bool),
			UnitsReserved:       1,
		}
		seq++
		w, anyQual := s.selectFairEligibleWorkerLocked(collAssign, st, baseTime, false)
		if w != nil {
			s.offerAssignmentToWorkerLocked(collAssign, w, now)
		} else if !anyQual && st.QualifiedCollectorRequired {
			noQualifiedCollector = true
		}
		s.state.Assignments[collAssign.AssignmentID] = collAssign
		j.AssignmentIDs = append(j.AssignmentIDs, collAssign.AssignmentID)
		j.CollectionAssignmentID = collAssign.AssignmentID
		j.CollectionAssignmentIDs = append(j.CollectionAssignmentIDs, collAssign.AssignmentID)
		activeAssignIDs = append(activeAssignIDs, collAssign.AssignmentID)
	}

	// 2. Transport assignments for each connection leg AND Node assignments for intermediate nodes
	for idx, cid := range route.ConnectionPath {
		conn := s.state.Connections[cid]
		fromID := route.NodePath[idx]
		toID := route.NodePath[idx+1]
		if conn != nil {
			fromID = conn.FromLocationID
			toID = conn.ToLocationID
		}

		// If idx == 0 and there is a node handler assigned to startNode (for collection point handoff) or intermediate node
		if idx == 0 && !presealed {
			// Check if any node handler is assigned to startNodeID
			if s.hasNodeHandlerAtLocationLocked(fromID) {
				outTo := toID
				nodeAssign := &AssignmentModel{
					AssignmentID:           newUUID(),
					Kind:                   "node",
					SampleID:               smp.SampleID,
					SampleIDs:              []string{smp.SampleID},
					JourneyID:              journeyID,
					Status:                 "pending",
					FromLocationID:         fromID,
					ToLocationID:           fromID,
					NodeID:                 fromID,
					IncomingFromLocationID: fromID,
					OutgoingToLocationID:   outTo,
					Sequence:               seq,
					History:                []TimelineEntry{},
					DeclinedByWorkerIDs:    make(map[string]bool),
					UnitsReserved:          1,
				}
				seq++
				if nw, _ := s.selectFairEligibleWorkerLocked(nodeAssign, st, baseTime, false); nw != nil {
					s.offerAssignmentToWorkerLocked(nodeAssign, nw, now)
				}
				s.state.Assignments[nodeAssign.AssignmentID] = nodeAssign
				j.AssignmentIDs = append(j.AssignmentIDs, nodeAssign.AssignmentID)
				j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, nodeAssign.AssignmentID)
				activeAssignIDs = append(activeAssignIDs, nodeAssign.AssignmentID)
			}
		}

		trAssign := &AssignmentModel{
			AssignmentID:        newUUID(),
			Kind:                "transport",
			SampleID:            smp.SampleID,
			SampleIDs:           []string{smp.SampleID},
			JourneyID:           journeyID,
			Status:              "pending",
			FromLocationID:      fromID,
			ToLocationID:        toID,
			ConnectionID:        cid,
			Sequence:            seq,
			History:             []TimelineEntry{},
			DeclinedByWorkerIDs: make(map[string]bool),
			UnitsReserved:       1,
		}
		seq++
		if tw, _ := s.selectFairEligibleWorkerLocked(trAssign, st, baseTime, false); tw != nil {
			s.offerAssignmentToWorkerLocked(trAssign, tw, now)
		}
		s.state.Assignments[trAssign.AssignmentID] = trAssign
		j.AssignmentIDs = append(j.AssignmentIDs, trAssign.AssignmentID)
		j.TransportAssignmentIDs = append(j.TransportAssignmentIDs, trAssign.AssignmentID)
		activeAssignIDs = append(activeAssignIDs, trAssign.AssignmentID)

		// If toID is an intermediate node (not the final destination), create a node assignment
		if idx < len(route.ConnectionPath)-1 {
			nextToID := route.NodePath[idx+2]
			nodeAssign := &AssignmentModel{
				AssignmentID:           newUUID(),
				Kind:                   "node",
				SampleID:               smp.SampleID,
				SampleIDs:              []string{smp.SampleID},
				JourneyID:              journeyID,
				Status:                 "pending",
				FromLocationID:         toID,
				ToLocationID:           toID,
				NodeID:                 toID,
				IncomingFromLocationID: fromID,
				OutgoingToLocationID:   nextToID,
				Sequence:               seq,
				History:                []TimelineEntry{},
				DeclinedByWorkerIDs:    make(map[string]bool),
				UnitsReserved:          1,
			}
			seq++
			if nw, _ := s.selectFairEligibleWorkerLocked(nodeAssign, st, baseTime, false); nw != nil {
				s.offerAssignmentToWorkerLocked(nodeAssign, nw, now)
			}
			s.state.Assignments[nodeAssign.AssignmentID] = nodeAssign
			j.AssignmentIDs = append(j.AssignmentIDs, nodeAssign.AssignmentID)
			j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, nodeAssign.AssignmentID)
			activeAssignIDs = append(activeAssignIDs, nodeAssign.AssignmentID)
		}
	}

	// Populate first/middle/finalTransportAssignmentId
	if len(j.TransportAssignmentIDs) > 0 {
		j.FirstTransportAssignmentID = j.TransportAssignmentIDs[0]
		j.FinalTransportAssignmentID = j.TransportAssignmentIDs[len(j.TransportAssignmentIDs)-1]
		if len(j.TransportAssignmentIDs) >= 3 {
			j.MiddleTransportAssignmentID = j.TransportAssignmentIDs[1]
		} else if len(j.TransportAssignmentIDs) == 2 {
			j.MiddleTransportAssignmentID = j.TransportAssignmentIDs[1]
		}
	}

	// 3. Laboratory assignment at TargetLabID
	if route.TargetLabID != "" {
		labAssign := &AssignmentModel{
			AssignmentID:         newUUID(),
			Kind:                 "laboratory",
			SampleID:             smp.SampleID,
			SampleIDs:            []string{smp.SampleID},
			JourneyID:            journeyID,
			Status:               "pending",
			FromLocationID:       route.TargetLabID,
			ToLocationID:         route.TargetLabID,
			LaboratoryID:         route.TargetLabID,
			ExpectedSampleTypeID: smp.SampleTypeID,
			Sequence:             seq,
			History:              []TimelineEntry{},
			DeclinedByWorkerIDs:  make(map[string]bool),
			UnitsReserved:        1,
		}
		seq++
		if lw, _ := s.selectFairEligibleWorkerLocked(labAssign, st, baseTime, false); lw != nil {
			s.offerAssignmentToWorkerLocked(labAssign, lw, now)
		}
		s.state.Assignments[labAssign.AssignmentID] = labAssign
		j.AssignmentIDs = append(j.AssignmentIDs, labAssign.AssignmentID)
		j.LaboratoryAssignmentIDs = append(j.LaboratoryAssignmentIDs, labAssign.AssignmentID)
		activeAssignIDs = append(activeAssignIDs, labAssign.AssignmentID)
	}

	if noQualifiedCollector {
		smp.Status = "exception"
		smp.Exception = map[string]interface{}{
			"reason":     "no_qualified_worker",
			"code":       "no_qualified_worker",
			"occurredAt": formatTime(now),
		}
		j.Status = "exception"
		j.ReplanStatus = "exception"
		ev := s.recordAuditLocked(actorID, actorRole, "sample_exception", "sample", smp.SampleID, true, now, map[string]interface{}{
			"sampleId": smp.SampleID,
			"reason":   "no_qualified_worker",
		})
		smp.Timeline = append(smp.Timeline, ev)
	}

	evJ := s.recordAuditLocked(actorID, actorRole, "create_journey", "journey", j.JourneyID, true, now, map[string]interface{}{
		"journeyId": j.JourneyID,
		"sampleIds": j.SampleIDs,
		"routeMode": j.RouteMode,
	})
	j.History = append(j.History, evJ)

	s.state.Journeys[j.JourneyID] = j
	return j, activeAssignIDs, nil
}

func (s *Store) hasNodeHandlerAtLocationLocked(locationID string) bool {
	for _, u := range s.state.Users {
		if u.Active && hasRole(u, "node_handler") && u.AssignedLocationID == locationID {
			return true
		}
	}
	return false
}

func (s *Store) buildJourneyPlanDTO(j *JourneyModel) map[string]interface{} {
	if j == nil {
		return nil
	}
	legs := []JourneyLeg{}
	workerSet := map[string]bool{}
	var assignedWorkers []string

	for idx, aid := range j.AssignmentIDs {
		a := s.state.Assignments[aid]
		if a == nil {
			continue
		}
		leg := JourneyLeg{
			AssignmentID:    a.AssignmentID,
			AssignmentID2:   a.AssignmentID,
			Sequence:        idx + 1,
			Status:          a.Status,
			FromLocationID:  a.FromLocationID,
			FromLocationID2: a.FromLocationID,
			ToLocationID:    a.ToLocationID,
			ToLocationID2:   a.ToLocationID,
			WorkerID:        a.WorkerID,
			WorkerID2:       a.WorkerID,
			SampleID:        a.SampleID,
		}
		legs = append(legs, leg)
		if a.WorkerID != "" && !workerSet[a.WorkerID] {
			workerSet[a.WorkerID] = true
			assignedWorkers = append(assignedWorkers, a.WorkerID)
		}
	}
	if assignedWorkers == nil {
		assignedWorkers = []string{}
	}
	stops := j.OrderedStops
	if stops == nil {
		stops = []JourneyStop{}
	}
	sids := j.SampleIDs
	if sids == nil {
		sids = []string{}
	}
	collIDs := j.CollectionAssignmentIDs
	if collIDs == nil {
		collIDs = []string{}
	}
	nodeIDs := j.NodeAssignmentIDs
	if nodeIDs == nil {
		nodeIDs = []string{}
	}
	labIDs := j.LaboratoryAssignmentIDs
	if labIDs == nil {
		labIDs = []string{}
	}

	res := map[string]interface{}{
		"journeyId":               j.JourneyID,
		"planVersion":             j.PlanVersion,
		"routeMode":               j.RouteMode,
		"status":                  j.Status,
		"estimatedDeliveryAt":     j.EstimatedDeliveryAt,
		"totalCostUnits":          j.TotalCostUnits,
		"capacityUsed":            j.CapacityUsed,
		"capacityAvailable":       j.CapacityAvailable,
		"sampleIds":               sids,
		"orderedStops":            stops,
		"legs":                    legs,
		"assignedWorkerIds":       assignedWorkers,
		"collectionAssignmentIds": collIDs,
		"nodeAssignmentIds":       nodeIDs,
		"laboratoryAssignmentIds": labIDs,
		"valid":                   j.Valid,
	}
	if j.ParentJourneyID != "" {
		res["parentJourneyId"] = j.ParentJourneyID
	}
	if j.CollectionAssignmentID != "" {
		res["collectionAssignmentId"] = j.CollectionAssignmentID
	}
	if j.FirstTransportAssignmentID != "" {
		res["firstTransportAssignmentId"] = j.FirstTransportAssignmentID
	}
	if j.MiddleTransportAssignmentID != "" {
		res["middleTransportAssignmentId"] = j.MiddleTransportAssignmentID
	}
	if j.FinalTransportAssignmentID != "" {
		res["finalTransportAssignmentId"] = j.FinalTransportAssignmentID
	}
	if j.ReplanStatus != "" {
		res["replanStatus"] = j.ReplanStatus
	}
	if j.SplitJourneyID != "" {
		if sj := s.state.Journeys[j.SplitJourneyID]; sj != nil {
			res["splitJourney"] = s.buildJourneyPlanDTO(sj)
		}
	}
	if j.ReplacementJourneyID != "" {
		if rj := s.state.Journeys[j.ReplacementJourneyID]; rj != nil {
			res["replacementJourney"] = s.buildJourneyPlanDTO(rj)
		}
	}
	return res
}

func (s *Store) buildWorkerJourneyPlanDTO(j *JourneyModel, workerID string) map[string]interface{} {
	var myAssignIDs []string
	var myLegs []JourneyLeg
	myLocs := map[string]bool{}
	mySamples := map[string]bool{}
	var sampleIDs []string

	for idx, aid := range j.AssignmentIDs {
		a := s.state.Assignments[aid]
		if a == nil {
			continue
		}
		if a.WorkerID == workerID || a.OfferedToWorkerID == workerID {
			myAssignIDs = append(myAssignIDs, a.AssignmentID)
			myLegs = append(myLegs, JourneyLeg{
				AssignmentID:    a.AssignmentID,
				AssignmentID2:   a.AssignmentID,
				Sequence:        idx + 1,
				Status:          a.Status,
				FromLocationID:  a.FromLocationID,
				FromLocationID2: a.FromLocationID,
				ToLocationID:    a.ToLocationID,
				ToLocationID2:   a.ToLocationID,
				WorkerID:        a.WorkerID,
				WorkerID2:       a.WorkerID,
				SampleID:        a.SampleID,
			})
			if a.FromLocationID != "" {
				myLocs[a.FromLocationID] = true
			}
			if a.ToLocationID != "" {
				myLocs[a.ToLocationID] = true
			}
			if a.NodeID != "" {
				myLocs[a.NodeID] = true
			}
			if a.LaboratoryID != "" {
				myLocs[a.LaboratoryID] = true
			}
			if a.SampleID != "" && !mySamples[a.SampleID] {
				mySamples[a.SampleID] = true
				sampleIDs = append(sampleIDs, a.SampleID)
			}
		}
	}
	if myAssignIDs == nil {
		myAssignIDs = []string{}
	}
	if myLegs == nil {
		myLegs = []JourneyLeg{}
	}
	if sampleIDs == nil {
		sampleIDs = []string{}
	}

	var myStops []JourneyStop
	for _, st := range j.OrderedStops {
		if myLocs[st.LocationID] {
			myStops = append(myStops, st)
		}
	}
	if myStops == nil {
		myStops = []JourneyStop{}
	}

	res := map[string]interface{}{
		"journeyId":           j.JourneyID,
		"planVersion":         j.PlanVersion,
		"routeMode":           j.RouteMode,
		"status":              j.Status,
		"estimatedDeliveryAt": j.EstimatedDeliveryAt,
		"scope":               "assigned_legs",
		"assignmentIds":       myAssignIDs,
		"sampleIds":           sampleIDs,
		"legs":                myLegs,
		"orderedStops":        myStops,
		"assignedWorkerIds":   []string{workerID},
	}
	if j.ParentJourneyID != "" {
		res["parentJourneyId"] = j.ParentJourneyID
	}
	return res
}

func (s *Store) buildRequesterJourneyPlanDTO(j *JourneyModel, requesterID string) map[string]interface{} {
	var mySamples []string
	for _, sid := range j.SampleIDs {
		if smp := s.state.Samples[sid]; smp != nil && smp.RequesterID == requesterID {
			mySamples = append(mySamples, sid)
		}
	}
	if mySamples == nil {
		mySamples = j.SampleIDs
	}
	var legs []map[string]interface{}
