			"toLocationId":   a.ToLocationID,
		})
	}
	if legs == nil {
		legs = []map[string]interface{}{}
	}
	stops := j.OrderedStops
	if stops == nil {
		stops = []JourneyStop{}
	}
	res := map[string]interface{}{
		"journeyId":           j.JourneyID,
		"planVersion":         j.PlanVersion,
		"routeMode":           j.RouteMode,
		"status":              j.Status,
		"estimatedDeliveryAt": j.EstimatedDeliveryAt,
		"totalCostUnits":      j.TotalCostUnits,
		"sampleIds":           mySamples,
		"orderedStops":        stops,
		"legs":                legs,
	}
	if j.ParentJourneyID != "" {
		res["parentJourneyId"] = j.ParentJourneyID
	}
	return res
}
