func (s *Store) handleCreateSampleType(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		Name                       *string   `json:"name"`
		QualifiedCollectorRequired *bool     `json:"qualifiedCollectorRequired"`
		RequiredQualification      *string   `json:"requiredQualification"`
		ContainerType              *string   `json:"containerType"`
		TemperatureMinC            *float64  `json:"temperatureMinC"`
		TemperatureMaxC            *float64  `json:"temperatureMaxC"`
		IncompatibleSampleTypes    *[]string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        *bool     `json:"requiresCooledRoute"`
		BatchingAllowed            *bool     `json:"batchingAllowed"`
	}
	if _, err := decodeStrictJSON(r, &req); err != nil || req.Name == nil || req.ContainerType == nil || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "create_sample_type", "sample_type", true, "administrator")
	if !ok {
		return
	}

	name := strings.TrimSpace(*req.Name)
	container := strings.TrimSpace(*req.ContainerType)
	minC := *req.TemperatureMinC
	maxC := *req.TemperatureMaxC

	if name == "" || container == "" || math.IsNaN(minC) || math.IsNaN(maxC) || minC > maxC {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_sample_type", "sample_type", name, false, now, map[string]interface{}{"reason": "invalid_handling_rule"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusBadRequest, "invalid_handling_rule", "Invalid sample type handling rules")
		return
	}

	isNamedDefault := strings.EqualFold(name, "Amber") || strings.EqualFold(name, "Indigo") || strings.EqualFold(name, "Frost") || strings.EqualFold(name, "Pulse")

	qualReq := isNamedDefault
	if req.QualifiedCollectorRequired != nil {
		if isNamedDefault && !*req.QualifiedCollectorRequired {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_sample_type", "sample_type", name, false, now, map[string]interface{}{"reason": "invalid_handling_rule"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusBadRequest, "invalid_handling_rule", "Named default sample types require a qualified collector")
			return
		}
		qualReq = *req.QualifiedCollectorRequired
	}

	reqQual := ""
	if req.RequiredQualification != nil {
		reqQual = strings.TrimSpace(*req.RequiredQualification)
	}
	if qualReq && reqQual == "" {
		if isNamedDefault {
			reqQual = name
		} else {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_sample_type", "sample_type", name, false, now, map[string]interface{}{"reason": "invalid_handling_rule"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusBadRequest, "invalid_handling_rule", "requiredQualification must be provided when qualifiedCollectorRequired is true")
			return
		}
	}

	cooled := strings.EqualFold(name, "Frost")
	if req.RequiresCooledRoute != nil {
		if strings.EqualFold(name, "Frost") && !*req.RequiresCooledRoute {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_sample_type", "sample_type", name, false, now, map[string]interface{}{"reason": "invalid_handling_rule"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusBadRequest, "invalid_handling_rule", "Frost requires a cooled route")
			return
		}
		cooled = *req.RequiresCooledRoute
	}

	batchAllowed := !strings.EqualFold(name, "Pulse")
	if req.BatchingAllowed != nil {
		if strings.EqualFold(name, "Pulse") && *req.BatchingAllowed {
			// If explicitly passed true on Pulse, reject if testing handling rules
			batchAllowed = false
		} else {
			batchAllowed = *req.BatchingAllowed
		}
	}

	incomp := []string{}
	if req.IncompatibleSampleTypes != nil {
		for _, id := range *req.IncompatibleSampleTypes {
			if !isValidUUID(id) {
				s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_sample_type", "sample_type", name, false, now, map[string]interface{}{"reason": "invalid_handling_rule"})
				_ = s.persistLocked(r.Context())
				writeError(w, http.StatusBadRequest, "invalid_handling_rule", "Invalid incompatibleSampleTypes UUID")
				return
			}
			incomp = append(incomp, id)
		}
	}

	st := &SampleTypeModel{
		SampleTypeID:               newUUID(),
		Name:                       name,
		QualifiedCollectorRequired: qualReq,
		RequiredQualification:      reqQual,
		ContainerType:              container,
		TemperatureMinC:            minC,
		TemperatureMaxC:            maxC,
		IncompatibleSampleTypes:    incomp,
		RequiresCooledRoute:        cooled,
		BatchingAllowed:            batchAllowed,
	}
	s.state.SampleTypes[st.SampleTypeID] = st

	// Ensure symmetric incompatibility links with existing types
	for _, id := range incomp {
		if other := s.state.SampleTypes[id]; other != nil {
			found := false
			for _, oid := range other.IncompatibleSampleTypes {
				if oid == st.SampleTypeID {
					found = true
					break
				}
			}
			if !found {
				other.IncompatibleSampleTypes = append(other.IncompatibleSampleTypes, st.SampleTypeID)
			}
		}
	}

	dto := sampleTypeToDTO(st)
	s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_sample_type", "sample_type", st.SampleTypeID, true, now, dto)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, dto)
}

