	}

	s.mu.Lock()
	defer s.mu.Unlock()

	actor, sess, ok := s.authAndRoleLocked(w, r, "record_laboratory_exception", "sample", true, "laboratory_team")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("record_laboratory_exception", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	smp := s.state.Samples[*req.SampleID]
	lab := s.state.Locations[*req.LaboratoryID]
	if smp == nil || lab == nil {
		writeError(w, http.StatusNotFound, "not_found", "Sample or laboratory not found")
		return
	}
	if actor.AssignedLocationID != "" && actor.AssignedLocationID != lab.LocationID {
