		"sampleId":     smp.SampleID,
		"laboratoryId": lab.LocationID,
		"reason":       reasonStr,
		"observedAt":   formatTime(obsAt),
		"recordedBy":   actor.UserID,
	}

	if j := s.state.Journeys[smp.ActiveJourneyID]; j != nil {
		j.Status = "exception"
		s.releaseJourneyCapacityLocked(j)
		s.recomputeServiceabilitySnapshotLocked()
	}

	ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "record_laboratory_exception", "sample", smp.SampleID, true, obsAt, smp.Exception)
	smp.Timeline = append(smp.Timeline, ev)

