		"sampleId":    smp.SampleID,
		"status":      "exception",
		"reason":      reasonStr,
	}
	s.saveIdempotencyLocked("record_laboratory_exception", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("sample.exception", "sample", smp.SampleID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}
