func (s *Store) canUserAccessSampleLocked(u *User, role string, smp *SampleModel) bool {
	if u == nil || smp == nil {
		return false
	}
	if role == "administrator" || role == "dispatcher" {
		return true
	}
	if role == "requester" {
		return smp.RequesterID == u.UserID
	}
	if smp.CurrentHolderID == u.UserID {
		return true
	}
	for _, a := range s.state.Assignments {
		if a.SampleID == smp.SampleID && (a.WorkerID == u.UserID || a.OfferedToWorkerID == u.UserID) {
			return true
		}
		for _, sid := range a.SampleIDs {
			if sid == smp.SampleID && (a.WorkerID == u.UserID || a.OfferedToWorkerID == u.UserID) {
				return true
			}
		}
	}
	if role == "node_handler" && u.AssignedLocationID != "" && smp.CurrentLocationID == u.AssignedLocationID {
		return true
	}
	if role == "laboratory_team" && u.AssignedLocationID != "" && (smp.TargetLaboratoryID == u.AssignedLocationID || smp.ReceivedLaboratoryID == u.AssignedLocationID) {
		return true
	}
	return false
}

