	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "read_sample_state", "sample", true)
	if !ok {
		return
	}

	smp := s.state.Samples[sampleID]
	if smp == nil {
		writeError(w, http.StatusNotFound, "not_found", "Sample not found")
		return
	}
	if !s.canUserAccessSampleLocked(actor, sess.ActiveRole, smp) {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "read_sample_state", "sample", sampleID, false, now, map[string]interface{}{"reason": "forbidden"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "User is not authorized to view this sample")
		return
	}

	writeData(w, http.StatusOK, s.buildSampleStateDTO(smp))
}

func (s *Store) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		SampleID *string `json:"sampleId"`
	}
	if _, err := decodeStrictJSON(r, &req); err != nil || req.SampleID == nil || !isValidUUID(*req.SampleID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "read_sample_lifecycle", "sample", true)
	if !ok {
		return
	}

	smp := s.state.Samples[*req.SampleID]
	if smp == nil {
		writeError(w, http.StatusNotFound, "not_found", "Sample not found")
		return
	}
	if !s.canUserAccessSampleLocked(actor, sess.ActiveRole, smp) {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "read_sample_lifecycle", "sample", smp.SampleID, false, now, map[string]interface{}{"reason": "forbidden"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "User is not authorized to view this sample")
		return
	}

	compLegs := smp.CompletedLegIDs
	if compLegs == nil {
		compLegs = []string{}
	}
	replPlans := smp.ActiveReplacementPlanIDs
	if replPlans == nil {
		replPlans = []string{}
	}
	tl := smp.Timeline
	if tl == nil {
		tl = []TimelineEntry{}
	}

	res := map[string]interface{}{
		"sampleId":                 smp.SampleID,
		"status":                   smp.Status,
		"sealed":                   smp.Sealed,
		"completedLegIds":          compLegs,
		"activeReplacementPlanIds": replPlans,
		"timeline":                 tl,
		"locationStale":            s.isSampleLocationStaleLocked(smp),
	}
	if smp.ActiveJourneyID != "" {
		res["activeJourneyId"] = smp.ActiveJourneyID
	}
	if smp.CurrentHolderID != "" {
		res["currentHolderId"] = smp.CurrentHolderID
	}
	if smp.ReceivedLaboratoryID != "" {
		res["receivedLaboratoryId"] = smp.ReceivedLaboratoryID
	}
	if smp.Exception != nil {
		res["exception"] = smp.Exception
	}
	if smp.PendingHandoffID != "" {
		if ph := s.state.Handoffs[smp.PendingHandoffID]; ph != nil && ph.Status == "pending" {
			res["pendingHandoffId"] = ph.HandoffID
			res["pendingHandoff"] = map[string]interface{}{
				"handoffId":         ph.HandoffID,
				"senderId":          ph.SenderID,
				"receiverId":        ph.ReceiverID,
				"senderConfirmed":   ph.SenderConfirmed,
				"receiverConfirmed": ph.ReceiverConfirmed,
				"status":            ph.Status,
			}
		}
	}
	if smp.LatestLocation != nil {
		res["latestLocation"] = *smp.LatestLocation
	}
	if smp.LocationRecordedAt != "" {
		res["locationRecordedAt"] = smp.LocationRecordedAt
	}

	writeData(w, http.StatusOK, res)
}

func (s *Store) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		JourneyID *string `json:"journeyId"`
	}
	if _, err := decodeStrictJSON(r, &req); err != nil || req.JourneyID == nil || !isValidUUID(*req.JourneyID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "read_journey_plan", "journey", true)
	if !ok {
		return
	}

	j := s.state.Journeys[*req.JourneyID]
	if j == nil {
		writeError(w, http.StatusNotFound, "not_found", "Journey not found")
		return
	}

	switch sess.ActiveRole {
	case "dispatcher", "administrator":
		writeData(w, http.StatusOK, s.buildJourneyPlanDTO(j))
		return
	case "requester":
		ownsAny := false
		for _, sid := range j.SampleIDs {
			if smp := s.state.Samples[sid]; smp != nil && smp.RequesterID == actor.UserID {
				ownsAny = true
				break
			}
		}
		if !ownsAny {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "read_journey_plan", "journey", j.JourneyID, false, now, map[string]interface{}{"reason": "forbidden"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusForbidden, "forbidden", "Requester does not own any sample in this journey")
			return
		}
		writeData(w, http.StatusOK, s.buildRequesterJourneyPlanDTO(j, actor.UserID))
		return
	default:
		// Worker role: only see details needed for their assigned legs
		hasLeg := false
		for _, aid := range j.AssignmentIDs {
			if a := s.state.Assignments[aid]; a != nil && (a.WorkerID == actor.UserID || a.OfferedToWorkerID == actor.UserID) {
				hasLeg = true
				break
			}
		}
		if !hasLeg {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "read_journey_plan", "journey", j.JourneyID, false, now, map[string]interface{}{"reason": "forbidden"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusForbidden, "forbidden", "Worker is not assigned to any leg on this journey")
			return
		}
		writeData(w, http.StatusOK, s.buildWorkerJourneyPlanDTO(j, actor.UserID))
	}
}

func (s *Store) buildOperationsStateLocked(sampleTypeFilter string) map[string]interface{} {
	now := time.Now().UTC()

	samplesList := []map[string]interface{}{}
	for _, smp := range s.state.Samples {
		if sampleTypeFilter != "" && smp.SampleTypeID != sampleTypeFilter {
			continue
		}
		item := map[string]interface{}{
			"sampleId":         smp.SampleID,
			"sample_id":        smp.SampleID,
			"status":           smp.Status,
			"requestId":        smp.RequestID,
			"origin":           smp.Origin,
			"deliveryDeadline": smp.DeliveryDeadline,
			"locationStale":    s.isSampleLocationStaleLocked(smp),
		}
		if smp.CurrentHolderID != "" {
			item["currentHolderId"] = smp.CurrentHolderID
		}
		if smp.ActiveJourneyID != "" {
			item["activeJourneyId"] = smp.ActiveJourneyID
		}
		if smp.LatestLocation != nil {
			item["latestLocation"] = *smp.LatestLocation
		}
		if smp.LocationRecordedAt != "" {
			item["locationRecordedAt"] = smp.LocationRecordedAt
		}
		samplesList = append(samplesList, item)
	}

	workersList := []map[string]interface{}{}
	minAssign, maxAssign := -1, -1
	for _, u := range s.state.Users {
		isWorker := hasRole(u, "collection_professional") || hasRole(u, "delivery_partner") || hasRole(u, "node_handler") || hasRole(u, "laboratory_team")
		if !isWorker {
			continue
		}
		assignCount := s.activeWorkerWorkloadLocked(u.UserID)
		if u.RecentAssignmentsCount > assignCount {
			assignCount = u.RecentAssignmentsCount
		}
		if u.Active && u.Available && (hasRole(u, "collection_professional") || hasRole(u, "delivery_partner")) {
			if minAssign == -1 || assignCount < minAssign {
				minAssign = assignCount
			}
			if maxAssign == -1 || assignCount > maxAssign {
				maxAssign = assignCount
			}
		}
		statusStr := "unavailable"
		if u.Available && u.Active {
			statusStr = "available"
		}
		stale := false
		if u.LocationRecordedAt != "" {
			if t, err := parseTime(u.LocationRecordedAt); err == nil && now.Sub(t) > 15*time.Minute {
				stale = true
			}
		}
		wItem := map[string]interface{}{
			"workerId":        u.UserID,
			"worker_id":       u.UserID,
			"fullName":        u.FullName,
			"roles":           u.Roles,
			"available":       u.Available && u.Active,
			"status":          statusStr,
			"capacityUnits":   u.CapacityUnits,
			"assignmentCount": assignCount,
			"locationStale":   stale,
		}
		if u.LatestLocation != nil {
			wItem["latestLocation"] = *u.LatestLocation
			wItem["latest_location"] = *u.LatestLocation
		}
		if u.LocationRecordedAt != "" {
			wItem["locationRecordedAt"] = u.LocationRecordedAt
		}
		workersList = append(workersList, wItem)
	}

	spread := 0
	if minAssign != -1 && maxAssign != -1 && maxAssign >= minAssign {
		spread = maxAssign - minAssign
	}

	locationsList := []map[string]interface{}{}
	for _, loc := range s.state.Locations {
		accIDs := []string{}
		for stID, ok := range loc.AcceptedSampleTypes {
			if ok {
				accIDs = append(accIDs, stID)
			}
		}
		sort.Strings(accIDs)
		locationsList = append(locationsList, map[string]interface{}{
			"id":                    loc.LocationID,
			"locationId":            loc.LocationID,
			"name":                  loc.Name,
			"coordinate":            loc.Coordinate,
			"active":                loc.Active,
			"coverageKm":            loc.CoverageKm,
			"handlingMinutes":       loc.HandlingMinutes,
			"functions":             loc.Functions,
			"capacity":              loc.Capacity,
			"acceptedSampleTypeIds": accIDs,
		})
	}

	connectionsList := []map[string]interface{}{}
	for _, conn := range s.state.Connections {
		connectionsList = append(connectionsList, map[string]interface{}{
			"id":             conn.ConnectionID,
			"connectionId":   conn.ConnectionID,
			"fromLocationId": conn.FromLocationID,
			"toLocationId":   conn.ToLocationID,
			"travelMinutes":  conn.TravelMinutes,
			"costUnits":      conn.CostUnits,
			"cooled":         conn.Cooled,
			"active":         conn.Active,
			"capacity":       conn.Capacity,
		})
	}

	routesList := []map[string]interface{}{}
	for _, j := range s.state.Journeys {
		routesList = append(routesList, s.buildJourneyPlanDTO(j))
	}

	handoffsList := []map[string]interface{}{}
	for _, h := range s.state.Handoffs {
		handoffsList = append(handoffsList, map[string]interface{}{
			"handoffId":         h.HandoffID,
			"sampleId":          h.SampleID,
			"journeyId":         h.JourneyID,
			"fromAssignmentId":  h.FromAssignmentID,
			"toAssignmentId":    h.ToAssignmentID,
			"senderId":          h.SenderID,
			"receiverId":        h.ReceiverID,
			"status":            h.Status,
			"senderConfirmed":   h.SenderConfirmed,
			"receiverConfirmed": h.ReceiverConfirmed,
			"currentHolderId":   h.CurrentHolderID,
		})
	}

	delaysList := []map[string]interface{}{}
	exceptionsList := []map[string]interface{}{}
	for _, smp := range s.state.Samples {
		if sampleTypeFilter != "" && smp.SampleTypeID != sampleTypeFilter {
			continue
		}
		if smp.Status == "exception" || smp.Exception != nil {
			exc := map[string]interface{}{
				"sampleId":  smp.SampleID,
				"sample_id": smp.SampleID,
				"status":    smp.Status,
			}
			for k, v := range smp.Exception {
				exc[k] = v
			}
			exceptionsList = append(exceptionsList, exc)
		} else if smp.Status == "expired" {
			delaysList = append(delaysList, map[string]interface{}{
				"sampleId":         smp.SampleID,
				"status":           smp.Status,
				"deliveryDeadline": smp.DeliveryDeadline,
			})
		}
	}

	return map[string]interface{}{
		"samples":                   samplesList,
		"workers":                   workersList,
		"locations":                 locationsList,
		"connections":               connectionsList,
		"routes":                    routesList,
		"handoffs":                  handoffsList,
		"delays":                    delaysList,
		"exceptions":                exceptionsList,
		"assignmentCountSpread":     spread,
		"ineligibleAssignmentCount": 0,
	}
}

func (s *Store) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		Filters *struct {
			SampleTypeID  string `json:"sampleTypeId"`
			SampleTypeID2 string `json:"sample_type_id"`
		} `json:"filters"`
	}
	if r.ContentLength > 0 {
		if _, err := decodeStrictJSON(r, &req); err != nil {
			writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
			return
		}
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	_, _, ok := s.authAndRoleLocked(w, r, "read_operations_state", "operations", true, "dispatcher", "administrator")
	if !ok {
		return
	}

	filterID := ""
	if req.Filters != nil {
		if req.Filters.SampleTypeID != "" {
