              style={{ width: '100%', padding: '0.5rem', boxSizing: 'border-box' }}
            />
          </div>
          <div style={{ marginBottom: '1rem' }}>
            <label htmlFor="login-password" style={{ display: 'block', fontWeight: 600, marginBottom: '0.25rem' }}>
              Password
            </label>
            <input
              id="login-password"
              name="password"
              type="password"
              value={passwordInput}
              onChange={(e) => setPasswordInput(e.target.value)}
              style={{ width: '100%', padding: '0.5rem', boxSizing: 'border-box' }}
            />
          </div>
          <button
            type="submit"
            style={{ padding: '0.6rem 1.2rem', background: '#0284c7', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer', fontWeight: 600 }}
          >
            Sign In
          </button>
        </form>
      </main>
    );
  }

  // Compute capacity items for laboratory_team / node_handler
  const capacityFromWork = allWorkItems.find((i) => i.destinationCapacity)?.destinationCapacity;
  const capacityLocations = ownLocations.length > 0 ? ownLocations : operationsState?.locations || [];

  return (
    <div style={{ fontFamily: 'sans-serif', maxWidth: '1280px', margin: '0 auto', padding: '1rem' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '2px solid #e2e8f0', paddingBottom: '0.75rem', marginBottom: '1rem' }}>
        <div>
          <h1 style={{ margin: 0, fontSize: '1.4rem' }}>Lab Sample Pickup &amp; Delivery System</h1>
          <div style={{ fontSize: '0.9rem', color: '#475569', marginTop: '0.25rem' }}>
            Signed in as: <strong>{user.username}</strong> ({user.userId}) | Current Active Role: <strong data-testid="active-role-badge">{activeRole || 'None selected'}</strong>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
          <div>
            <label htmlFor="active-role-select" style={{ marginRight: '0.5rem', fontWeight: 600 }}>
              Active Role
            </label>
            <select
              id="active-role-select"
              aria-label="Active Role"
              value={activeRole}
              onChange={(e) => handleRoleSwitch(e.target.value)}
              style={{ padding: '0.4rem' }}
            >
              {activeRole === '' && <option value="">-- Select Role --</option>}
              {(user.roles || []).map((r: string) => (
                <option key={r} value={r}>
                  {r}
                </option>
              ))}
            </select>
          </div>
          <button
            type="button"
            onClick={handleSignOut}
            style={{ padding: '0.45rem 0.9rem', background: '#dc2626', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
          >
            Sign Out
          </button>
        </div>
      </header>

      {user.roleSelectionRequired && (
        <div role="alert" style={{ padding: '0.75rem', marginBottom: '1rem', background: '#fef3c7', color: '#92400e', borderRadius: '4px' }}>
          Please select an active role to continue. Available roles: {(user.roles || []).join(', ')}
          <div style={{ marginTop: '0.5rem', display: 'flex', gap: '0.5rem' }}>
            {(user.roles || []).map((r: string) => (
              <button key={r} type="button" onClick={() => handleRoleSwitch(r)}>
                Use role: {r}
              </button>
            ))}
          </div>
        </div>
      )}

      {actionMessage && (
        <div role="status" style={{ padding: '0.75rem', marginBottom: '1rem', background: '#dcfce7', color: '#166534', borderRadius: '4px' }}>
          {actionMessage}
        </div>
      )}
      {actionError && (
        <div role="alert" style={{ padding: '0.75rem', marginBottom: '1rem', background: '#fee2e2', color: '#991b1b', borderRadius: '4px' }}>
          {actionError}
        </div>
      )}

      {/* Offline MapLibre GL JS + PMTiles Map */}
      <OfflineMap markers={mapMarkers} />

      {/* Role Work Section (Current Work & Past Work) */}
      <section aria-label="Role Work View" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 style={{ marginTop: 0 }}>My Role Work ({activeRole})</h2>
          <button type="button" onClick={() => loadRoleWork(activeRole)}>
            Refresh Work
          </button>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
          <div aria-label="Current Work">
            <h3>Current Work ({currentWork.length})</h3>
            {currentWork.length === 0 ? (
              <p>No active or offered assignments.</p>
            ) : (
              currentWork.map((item) => (
                <div key={item.assignmentId} style={{ border: '1px solid #94a3b8', borderRadius: '4px', padding: '0.75rem', marginBottom: '0.75rem' }}>
                  <div>
                    <strong>Assignment ID:</strong> {item.assignmentId}
                  </div>
                  <div>
                    <strong>Status:</strong> <span>{item.status}</span> | <strong>Leg Type:</strong> {item.legType}
                  </div>
                  {item.sampleId && (
                    <div>
                      <strong>Sample ID:</strong> {item.sampleId}{' '}
                      <button type="button" onClick={() => handleLookupSample(item.sampleId)}>
                        View Sample
                      </button>
                    </div>
                  )}
                  {item.journeyId && (
                    <div>
                      <strong>Journey ID:</strong> {item.journeyId}
                    </div>
                  )}
                  {item.destinationCapacity && (
                    <div style={{ marginTop: '0.35rem', fontSize: '0.9rem' }}>
                      <strong>Destination Capacity:</strong> Regular {item.destinationCapacity.availableUnits}/{item.destinationCapacity.capacityUnits} (Reserved: {item.destinationCapacity.reservedUnits}) | Cooled {item.destinationCapacity.cooledAvailableUnits}/{item.destinationCapacity.cooledCapacityUnits} (Reserved: {item.destinationCapacity.cooledReservedUnits})
                    </div>
                  )}
                  <div style={{ marginTop: '0.5rem', display: 'flex', gap: '0.5rem' }}>
                    {(item.status === 'offered' || item.status === 'pending') && (
                      <>
                        <button type="button" onClick={() => handleAcceptAssignment(item.assignmentId)}>
                          Accept Assignment
                        </button>
                        <button type="button" onClick={() => handleDeclineAssignment(item.assignmentId)}>
                          Decline Assignment
                        </button>
                      </>
                    )}
                  </div>
                  {item.history && item.history.length > 0 && (
                    <div style={{ marginTop: '0.5rem' }}>
                      <strong>Assignment Status Timeline:</strong>
                      <ol>
                        {item.history.map((h: any, idx: number) => (
                          <li key={h.eventId || idx}>
                            {h.action} ({h.role}) - {h.occurredAt}
                          </li>
                        ))}
                      </ol>
                    </div>
                  )}
                </div>
              ))
            )}
          </div>

          <div aria-label="Past Work">
            <h3>Past Work ({pastWork.length})</h3>
            {pastWork.length === 0 ? (
              <p>No completed assignments yet.</p>
            ) : (
              pastWork.map((item) => (
                <div key={item.assignmentId} style={{ border: '1px solid #cbd5e1', borderRadius: '4px', padding: '0.75rem', marginBottom: '0.75rem', background: '#f8fafc' }}>
                  <div>
                    <strong>Assignment ID:</strong> {item.assignmentId}
                  </div>
                  <div>
                    <strong>Status:</strong> <span>{item.status}</span> | <strong>Leg Type:</strong> {item.legType}
                  </div>
                  {item.sampleId && (
                    <div>
                      <strong>Sample ID:</strong> {item.sampleId}{' '}
                      <button type="button" onClick={() => handleLookupSample(item.sampleId)}>
                        View Sample
                      </button>
                    </div>
                  )}
                  {item.history && item.history.length > 0 && (
                    <div style={{ marginTop: '0.5rem' }}>
                      <strong>Assignment Status Timeline:</strong>
                      <ol>
                        {item.history.map((h: any, idx: number) => (
                          <li key={h.eventId || idx}>
                            {h.action} ({h.role}) - {h.occurredAt}
                          </li>
                        ))}
                      </ol>
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </section>

      {/* Field Worker Location Recording (collection_professional & delivery_partner) */}
      {(activeRole === 'collection_professional' || activeRole === 'delivery_partner') && (
        <section aria-label="Worker Location Recording" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
          <h2 style={{ marginTop: 0 }}>Record Worker Location</h2>
          <form onSubmit={(e) => handleRecordWorkerLocation(e)} style={{ display: 'flex', gap: '1rem', alignItems: 'flex-end', flexWrap: 'wrap' }}>
            <div>
              <label htmlFor="worker-lat" style={{ display: 'block', fontWeight: 600 }}>
                Latitude
              </label>
              <input
                id="worker-lat"
                type="number"
                step="any"
                value={workerLat}
                onChange={(e) => setWorkerLat(e.target.value)}
              />
            </div>
            <div>
              <label htmlFor="worker-lng" style={{ display: 'block', fontWeight: 600 }}>
                Longitude
              </label>
              <input
                id="worker-lng"
                type="number"
                step="any"
                value={workerLng}
                onChange={(e) => setWorkerLng(e.target.value)}
              />
            </div>
            <button type="submit">Record Location</button>
          </form>
          {lastRecordedLocation && (
            <div style={{ marginTop: '0.5rem' }}>
              Last Recorded Worker Coordinate: {lastRecordedLocation.coordinate.latitude}, {lastRecordedLocation.coordinate.longitude} (Freshness: {lastRecordedLocation.locationStale ? 'Stale' : 'Fresh'})
            </div>
          )}
        </section>
      )}

      {/* Laboratory / Node Capacity View & Configuration */}
      {(activeRole === 'laboratory_team' || activeRole === 'node_handler' || activeRole === 'administrator') && (
        <section aria-label="Laboratory Capacity" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
          <h2 style={{ marginTop: 0 }}>Facility Capacity Overview &amp; Configuration</h2>
          {capacityLocations.length > 0 ? (
            capacityLocations.map((loc: any) => (
              <div key={loc.locationId || loc.id} style={{ padding: '0.75rem', border: '1px solid #e2e8f0', borderRadius: '4px', marginBottom: '0.5rem' }}>
                <div>
                  <strong>Facility:</strong> {loc.name} ({loc.locationId || loc.id})
                </div>
                {loc.capacity && (
                  <div>
                    <span>Regular Capacity: {loc.capacity.capacityUnits}</span> |{' '}
                    <span>Regular Reserved: {loc.capacity.reservedUnits}</span> |{' '}
                    <span>Regular Available: {loc.capacity.availableUnits}</span> |{' '}
                    <span>Cooled Capacity: {loc.capacity.cooledCapacityUnits}</span> |{' '}
                    <span>Cooled Reserved: {loc.capacity.cooledReservedUnits}</span> |{' '}
                    <span>Cooled Available: {loc.capacity.cooledAvailableUnits}</span>
                  </div>
                )}
              </div>
            ))
          ) : capacityFromWork ? (
            <div style={{ padding: '0.75rem', border: '1px solid #e2e8f0', borderRadius: '4px', marginBottom: '0.5rem' }}>
              <span>Regular Capacity: {capacityFromWork.capacityUnits}</span> |{' '}
              <span>Regular Reserved: {capacityFromWork.reservedUnits}</span> |{' '}
              <span>Regular Available: {capacityFromWork.availableUnits}</span> |{' '}
              <span>Cooled Capacity: {capacityFromWork.cooledCapacityUnits}</span> |{' '}
              <span>Cooled Reserved: {capacityFromWork.cooledReservedUnits}</span> |{' '}
              <span>Cooled Available: {capacityFromWork.cooledAvailableUnits}</span>
            </div>
          ) : (
            <p>No facility capacity records loaded.</p>
          )}

          <form onSubmit={handleConfigureCapacity} style={{ display: 'flex', gap: '1rem', alignItems: 'flex-end', marginTop: '0.75rem', flexWrap: 'wrap' }}>
            <div>
              <label htmlFor="cap-target-id" style={{ display: 'block', fontWeight: 600 }}>
                Target Facility ID
              </label>
              <input
                id="cap-target-id"
                type="text"
                value={capTargetId}
                onChange={(e) => setCapTargetId(e.target.value)}
              />
            </div>
            <div>
              <label htmlFor="cap-regular" style={{ display: 'block', fontWeight: 600 }}>
                Regular Capacity Units
              </label>
              <input
                id="cap-regular"
                type="number"
                value={capRegular}
                onChange={(e) => setCapRegular(e.target.value)}
              />
            </div>
            <div>
              <label htmlFor="cap-cooled" style={{ display: 'block', fontWeight: 600 }}>
                Cooled Capacity Units
              </label>
              <input
                id="cap-cooled"
                type="number"
                value={capCooled}
                onChange={(e) => setCapCooled(e.target.value)}
              />
            </div>
            <button type="submit">Update Capacity</button>
          </form>
        </section>
      )}

      {/* Requester Serviceability Check & Collection Request Form */}
      {(activeRole === 'requester' || activeRole === 'administrator') && (
        <section aria-label="Collection Request Form" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
          <h2 style={{ marginTop: 0 }}>Check Serviceability &amp; Create Collection Request</h2>
          {requestFormError && (
            <div role="alert" style={{ padding: '0.75rem', marginBottom: '1rem', background: '#fee2e2', color: '#991b1b', borderRadius: '4px' }}>
              {requestFormError}
            </div>
          )}
          {serviceabilityResult && (
            <div role="status" aria-label="Serviceability Dry Run Result" style={{ padding: '0.75rem', marginBottom: '1rem', background: '#e0f2fe', color: '#075985', borderRadius: '4px' }}>
              <strong>Serviceability Check (Dry Run — No Request Created):</strong>{' '}
              <span>{serviceabilityResult.serviceable ? 'Serviceable' : 'Unserviceable'}</span> |{' '}
              <span>Reason: {serviceabilityResult.reason}</span> |{' '}
              <span>Version: {serviceabilityResult.serviceabilityVersion}</span>
              {serviceabilityResult.targetLaboratoryId && (
                <span> | Target Lab: {serviceabilityResult.targetLaboratoryId}</span>
              )}
            </div>
          )}
          <form onSubmit={handleCreateCollectionRequest}>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: '0.75rem', marginBottom: '0.75rem' }}>
              <div>
                <label htmlFor="req-origin-type" style={{ display: 'block', fontWeight: 600 }}>
                  Origin Type
                </label>
                <select id="req-origin-type" value={originType} onChange={(e) => setOriginType(e.target.value)} style={{ width: '100%', padding: '0.4rem' }}>
                  <option value="home">home</option>
                  <option value="clinic">clinic</option>
                  <option value="node">node</option>
                </select>
              </div>
              <div>
                <label htmlFor="req-origin-lat" style={{ display: 'block', fontWeight: 600 }}>
                  Origin Latitude
                </label>
                <input
                  id="req-origin-lat"
                  type="text"
                  value={originLat}
                  onChange={(e) => setOriginLat(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-origin-lng" style={{ display: 'block', fontWeight: 600 }}>
                  Origin Longitude
                </label>
                <input
                  id="req-origin-lng"
                  type="text"
                  value={originLng}
                  onChange={(e) => setOriginLng(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-sample-type" style={{ display: 'block', fontWeight: 600 }}>
                  Sample Type ID
                </label>
                <input
                  id="req-sample-type"
                  type="text"
                  placeholder="UUID of sample type"
                  value={sampleTypeId}
                  onChange={(e) => setSampleTypeId(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
                <div style={{ fontSize: '0.75rem', marginTop: '0.25rem' }}>
                  Presets:{' '}
                  {DEFAULT_SAMPLE_TYPES.map((st) => (
                    <button
                      key={st.id}
                      type="button"
                      onClick={() => {
                        setSampleTypeId(st.id);
                        setContainerType(st.container);
                        setTempMin(String(st.minC));
                        setTempMax(String(st.maxC));
                      }}
                      style={{ marginRight: '0.25rem', fontSize: '0.75rem' }}
                    >
                      {st.name}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <label htmlFor="req-container" style={{ display: 'block', fontWeight: 600 }}>
                  Container Type
                </label>
                <input
                  id="req-container"
                  type="text"
                  value={containerType}
                  onChange={(e) => setContainerType(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-temp-min" style={{ display: 'block', fontWeight: 600 }}>
                  Min Temperature (C)
                </label>
                <input
                  id="req-temp-min"
                  type="text"
                  value={tempMin}
                  onChange={(e) => setTempMin(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-temp-max" style={{ display: 'block', fontWeight: 600 }}>
                  Max Temperature (C)
                </label>
                <input
                  id="req-temp-max"
                  type="text"
                  value={tempMax}
                  onChange={(e) => setTempMax(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-window-start" style={{ display: 'block', fontWeight: 600 }}>
                  Earliest Collection Time
                </label>
                <input
                  id="req-window-start"
                  type="text"
                  value={windowStart}
                  onChange={(e) => setWindowStart(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-window-end" style={{ display: 'block', fontWeight: 600 }}>
                  Latest Collection Time
                </label>
                <input
                  id="req-window-end"
                  type="text"
                  value={windowEnd}
                  onChange={(e) => setWindowEnd(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-deadline" style={{ display: 'block', fontWeight: 600 }}>
                  Delivery Deadline
                </label>
                <input
                  id="req-deadline"
                  type="text"
                  value={deadlineAt}
                  onChange={(e) => setDeadlineAt(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
            </div>
            <div style={{ display: 'flex', gap: '0.75rem' }}>
              <button type="button" onClick={handleCheckServiceability}>
                Check Serviceability
              </button>
              <button type="submit">Create Collection Request</button>
            </div>
          </form>
        </section>
      )}

      {/* Sample Tracking, Freshness, Custodian, Route Progress, Exception Flag & Ordered Status History */}
      <section aria-label="Sample Tracking and Status History" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
        <h2 style={{ marginTop: 0 }}>Sample Tracking, Custody &amp; Status Timeline</h2>
        <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '0.75rem', alignItems: 'center' }}>
          <label htmlFor="sample-lookup-input" style={{ fontWeight: 600 }}>
            Inspect Sample ID:
          </label>
          <input
            id="sample-lookup-input"
            type="text"
            placeholder="Enter Sample UUID"
            value={sampleLookupId}
            onChange={(e) => setSampleLookupId(e.target.value)}
            style={{ width: '320px', padding: '0.4rem' }}
          />
          <button type="button" onClick={() => handleLookupSample()}>
            Load Sample
          </button>
        </div>

        {requesterSamples.length > 0 && (
          <div style={{ marginBottom: '0.75rem' }}>
            <strong>My Samples ({requesterSamples.length}):</strong>{' '}
            {requesterSamples.map((smp) => (
              <button
                key={smp.sampleId}
                type="button"
                onClick={() => setSelectedSample(smp)}
                style={{ marginRight: '0.5rem', marginBottom: '0.25rem' }}
              >
                {smp.sampleId.slice(0, 8)} ({smp.status})
              </button>
            ))}
          </div>
        )}

        {selectedSample ? (
          <div data-testid="sample-detail-card" style={{ border: '1px solid #94a3b8', borderRadius: '6px', padding: '1rem', background: '#f8fafc' }}>
            <h3>Sample {selectedSample.sampleId}</h3>

            {(selectedSample.status === 'exception' || selectedSample.exception) && (
              <div
                role="alert"
                aria-label="Sample Exception"
                style={{ padding: '0.75rem', marginBottom: '0.75rem', background: '#fee2e2', color: '#991b1b', borderRadius: '4px', fontWeight: 600 }}
              >
                Exception Flag: {selectedSample.exception?.code || 'exception'} — {selectedSample.exception?.reason || 'Sample flagged as exception'}
              </div>
            )}

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: '0.75rem', marginBottom: '0.75rem' }}>
              <div>
                <strong>Status:</strong> <span>{selectedSample.status}</span>
              </div>
              <div>
                <strong>Current Custodian:</strong>{' '}
                <span data-testid="sample-custodian">{selectedSample.currentHolderId || 'Unsealed / Origin'}</span>
              </div>
              <div>
                <strong>Current Location:</strong>{' '}
                <span data-testid="sample-location">
                  {selectedSample.lastKnownCoordinate
                    ? `${selectedSample.lastKnownCoordinate.latitude}, ${selectedSample.lastKnownCoordinate.longitude}`
                    : 'Unknown'}
                </span>
              </div>
              <div>
                <strong>Location Freshness:</strong>{' '}
                <span data-testid="sample-freshness" style={{ fontWeight: 700, color: selectedSample.locationStale ? '#dc2626' : '#16a34a' }}>
                  {selectedSample.locationStale ? 'Stale' : 'Fresh'}
                </span>{' '}
                (Last Updated: {selectedSample.locationRecordedAt || 'N/A'})
              </div>
              <div>
                <strong>Delivery Deadline:</strong> {selectedSample.deliveryDeadlineAt}
              </div>
              <div>
                <strong>Journey ID:</strong> {selectedSample.journeyId}
              </div>
            </div>

            {selectedSample.route && (
              <div style={{ marginBottom: '0.75rem' }}>
                <h4>Route Progress (Plan Version {selectedSample.route.planVersion} — {selectedSample.route.routeMode})</h4>
                <ol aria-label="Route Progress">
                  {(selectedSample.route.orderedStops || []).map((stop: any) => (
                    <li key={stop.sequence}>
                      Stop #{stop.sequence}: {stop.kind} at {stop.locationId} —{' '}
                      <strong>{stop.completed ? 'Completed' : 'Pending'}</strong>
                    </li>
                  ))}
                </ol>
              </div>
            )}

            <div>
              <h4>Ordered Status History</h4>
              <ol aria-label="Ordered Status History" data-testid="sample-status-history">
                {(selectedSample.history || []).map((ev: any, idx: number) => (
                  <li key={ev.eventId || idx}>
                    <strong>{ev.action}</strong> | Role: {ev.role} | Actor: {ev.actorId} | Time: {ev.occurredAt}
                  </li>
                ))}
              </ol>
            </div>
          </div>
        ) : (
          <p>Select or enter a Sample ID to view its status history, location freshness, custodian, and route progress.</p>
        )}
      </section>

      {/* Dispatcher & Administrator Operations Monitor Dashboard */}
      {(activeRole === 'dispatcher' || activeRole === 'administrator') && (
        <section aria-label="Operations Monitor Dashboard" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <h2 style={{ marginTop: 0 }}>Operations Monitor Dashboard</h2>
            <button type="button" onClick={() => loadMonitorAndAudit(activeRole)}>
              Refresh Monitor
            </button>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '1rem' }}>
            <div style={{ border: '1px solid #e2e8f0', padding: '0.75rem', borderRadius: '4px' }}>
              <h3>Samples ({operationsState?.samples?.length || 0})</h3>
              <ul>
                {(operationsState?.samples || []).map((s: any) => (
                  <li key={s.sampleId}>
                    <button type="button" onClick={() => setSelectedSample(s)} style={{ marginRight: '0.35rem' }}>
                      {s.sampleId.slice(0, 8)}
                    </button>
                    Status: <strong>{s.status}</strong> | Holder: {s.currentHolderId || 'None'} |{' '}
                    <span>{s.locationStale ? 'Stale' : 'Fresh'}</span>
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', padding: '0.75rem', borderRadius: '4px' }}>
              <h3>Workers ({operationsState?.workers?.length || 0})</h3>
              <ul>
                {(operationsState?.workers || []).map((w: any) => (
                  <li key={w.userId}>
                    {w.username} ({(w.roles || []).join(', ')}) — {w.available ? 'Available' : 'Unavailable'} |{' '}
                    {w.locationStale ? 'Stale' : 'Fresh'}
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', padding: '0.75rem', borderRadius: '4px' }}>
              <h3>Locations ({operationsState?.locations?.length || 0})</h3>
              <ul>
                {(operationsState?.locations || []).map((loc: any) => (
                  <li key={loc.locationId}>
                    {loc.name} ({loc.active ? 'Active' : 'Inactive'}) — Cap: {loc.capacity?.availableUnits}/{loc.capacity?.capacityUnits}, Cooled: {loc.capacity?.cooledAvailableUnits}/{loc.capacity?.cooledCapacityUnits}
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', padding: '0.75rem', borderRadius: '4px' }}>
              <h3>Routes ({operationsState?.routes?.length || 0}) &amp; Connections ({operationsState?.connections?.length || 0})</h3>
              <ul>
                {(operationsState?.routes || []).map((rt: any) => (
                  <li key={rt.journeyId}>
                    Journey {rt.journeyId.slice(0, 8)} (v{rt.planVersion}, {rt.routeMode}) — {rt.status}
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', padding: '0.75rem', borderRadius: '4px' }}>
              <h3>Handoffs ({operationsState?.handoffs?.length || 0}) &amp; Delays ({operationsState?.delays?.length || 0})</h3>
              <ul>
                {(operationsState?.handoffs || []).map((h: any) => (
                  <li key={h.handoffId}>
                    Handoff {h.handoffId.slice(0, 8)}: {h.fromHolderId?.slice(0, 6)} → {h.toHolderId?.slice(0, 6)} ({h.status})
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', padding: '0.75rem', borderRadius: '4px' }}>
              <h3>Exceptions ({operationsState?.exceptions?.length || 0})</h3>
              <ul>
                {(operationsState?.exceptions || []).map((ex: any) => (
                  <li key={ex.sampleId} style={{ color: '#991b1b' }}>
                    Sample {ex.sampleId.slice(0, 8)}: {ex.code} — {ex.reason}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </section>
      )}

      {/* Searchable Audit Trail (Dispatcher & Administrator) */}
      {(activeRole === 'dispatcher' || activeRole === 'administrator') && (
        <section aria-label="Audit Trail" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
          <h2 style={{ marginTop: 0 }}>Audit Trail Search</h2>
          <form onSubmit={handleSearchAudit} style={{ display: 'flex', gap: '0.75rem', flexWrap: 'wrap', alignItems: 'flex-end', marginBottom: '1rem' }}>
            <div>
              <label htmlFor="audit-search-input" style={{ display: 'block', fontWeight: 600 }}>
                Search Audit
              </label>
              <input
                id="audit-search-input"
                aria-label="Search Audit"
                type="text"
                placeholder="Query text, entity ID, actor..."
                value={auditQuery}
                onChange={(e) => setAuditQuery(e.target.value)}
                style={{ width: '240px', padding: '0.4rem' }}
              />
            </div>
            <div>
              <label htmlFor="audit-action-filter" style={{ display: 'block', fontWeight: 600 }}>
                Action Filter
              </label>
              <input
                id="audit-action-filter"
                type="text"
                placeholder="e.g. authenticate_user"
                value={auditActionFilter}
                onChange={(e) => setAuditActionFilter(e.target.value)}
                style={{ width: '180px', padding: '0.4rem' }}
              />
            </div>
            <div>
              <label htmlFor="audit-role-filter" style={{ display: 'block', fontWeight: 600 }}>
                Role Filter
              </label>
              <input
                id="audit-role-filter"
                type="text"
                placeholder="e.g. administrator"
                value={auditRoleFilter}
                onChange={(e) => setAuditRoleFilter(e.target.value)}
                style={{ width: '160px', padding: '0.4rem' }}
              />
            </div>
            <button type="submit">Search Audit</button>
          </form>

          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.9rem' }}>
            <thead>
              <tr style={{ background: '#f1f5f9', textAlign: 'left' }}>
                <th style={{ padding: '0.5rem', borderBottom: '1px solid #cbd5e1' }}>Event ID</th>
                <th style={{ padding: '0.5rem', borderBottom: '1px solid #cbd5e1' }}>Action</th>
                <th style={{ padding: '0.5rem', borderBottom: '1px solid #cbd5e1' }}>Role</th>
                <th style={{ padding: '0.5rem', borderBottom: '1px solid #cbd5e1' }}>Actor ID</th>
                <th style={{ padding: '0.5rem', borderBottom: '1px solid #cbd5e1' }}>Entity</th>
                <th style={{ padding: '0.5rem', borderBottom: '1px solid #cbd5e1' }}>Outcome</th>
                <th style={{ padding: '0.5rem', borderBottom: '1px solid #cbd5e1' }}>Occurred At</th>
              </tr>
            </thead>
            <tbody>
              {auditEntries.map((entry) => (
                <tr key={entry.eventId}>
                  <td style={{ padding: '0.4rem', borderBottom: '1px solid #e2e8f0' }}>{entry.eventId}</td>
                  <td style={{ padding: '0.4rem', borderBottom: '1px solid #e2e8f0' }}>{entry.action}</td>
                  <td style={{ padding: '0.4rem', borderBottom: '1px solid #e2e8f0' }}>{entry.role}</td>
                  <td style={{ padding: '0.4rem', borderBottom: '1px solid #e2e8f0' }}>{entry.actorId}</td>
                  <td style={{ padding: '0.4rem', borderBottom: '1px solid #e2e8f0' }}>
                    {entry.entityType}: {entry.entityId}
                  </td>
                  <td style={{ padding: '0.4rem', borderBottom: '1px solid #e2e8f0' }}>{entry.success ? 'Success' : 'Denied/Failed'}</td>
                  <td style={{ padding: '0.4rem', borderBottom: '1px solid #e2e8f0' }}>{entry.occurredAt}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      )}
    </div>
  );
}
